"""Class 10 NEW writing sets 1-5 (20 marks): formal letter (5) OR, analytical paragraph (5) OR; grammar 10 items (reuse 7 originals + 3 new)."""
import re
from eng_lib import Q, OR
def L(q, ans): return Q(q, ans, "5")
def A(q, ans): return Q(q, ans, "5")
def g(q, ans): return Q(q, ans, "1")
FL = "<br><i>(Format 1 · Content 2 · Organisation 1 · Language 1)</i>"
FA = "<br><i>(Content 2 · Organisation 1 · Analysis/Interpretation 1 · Language 1)</i>"
def tbl(h, rows):
    return "<table style='border-collapse:collapse;margin:3px auto;font-size:.92em'><tr>" + "".join(f"<th style='border:1px solid #999;padding:1px 8px;background:#eef1f8'>{x}</th>" for x in h) + "</tr>" + "".join("<tr>" + "".join(f"<td style='border:1px solid #999;padding:1px 8px;text-align:center'>{x}</td>" for x in r) + "</tr>" for r in rows) + "</table>"
AP = "Write an analytical paragraph in 100–120 words on the basis of the data given below."
EXTRA = {}; NEWB = {}; ANA = {}

NEWB[1] = L("You are Rohit/Rashmi, Secretary of the Literary Club of Mastermind Public School, Jaipur. Write a letter in 100–120 words to the Manager, Sahitya Book House, placing an order for books for the school library. Mention titles, number of copies and the discount expected.", "Mastermind Public School<br>Jaipur<br>10 November 2026<br>The Manager<br>Sahitya Book House<br>MI Road, Jaipur<br>Subject: Order for library books<br>Sir/Madam,<br>Kindly supply the following books for our school library: 'Wings of Fire' – 10 copies; 'Gitanjali' (English) – 8 copies; 'The Jungle Book' – 15 copies; Oxford Dictionary – 5 copies. We expect a discount of 20 per cent, as this is a bulk order. Please send the books with the bill within ten days. Payment will be made by cheque on delivery.<br>Yours faithfully<br>Rohit/Rashmi<br>Secretary, Literary Club" + FL)
ANA[1] = (A(AP + "<br><b>Mobile phone use by students of Class 10 (survey of 200 students)</b>" + tbl(["Purpose", "Percentage of students"], [["Games and videos", "45%"], ["Study-related use", "30%"], ["Social media", "20%"], ["Other", "5%"]]), "The table shows how 200 students of Class 10 use their mobile phones. The largest share, 45 per cent, use them for games and videos, which means that nearly half the students treat the phone as a toy. Only 30 per cent use it for study, even though it can be a useful tool. A further 20 per cent spend their time on social media, while 5 per cent use it for other purposes. Together, entertainment and social media account for 65 per cent of use. The data suggest that students need guidance on the productive use of technology. Schools may set time limits and encourage learning applications so that the phone becomes an aid to study rather than a distraction." + FA),
      A(AP + "<br><b>Water consumption in a household (litres per day)</b>" + tbl(["Use", "Litres"], [["Bathing", "80"], ["Cooking and drinking", "30"], ["Washing clothes", "40"], ["Cleaning and flushing", "50"]]), "The table gives the daily water use of a household, a total of 200 litres. Bathing consumes the most, 80 litres, which is 40 per cent of the total. Cleaning and flushing use 50 litres (25 per cent), and washing clothes uses 40 litres (20 per cent). Cooking and drinking, the most essential use, need only 30 litres, or 15 per cent. It is therefore clear that most of the water is used for needs that can be reduced. By using buckets instead of showers, repairing leaking taps and reusing water from washing, a family can save a large quantity. Small steps at home can make a big difference to the community's water supply." + FA))
ANA[2] = (A(AP + "<br><b>Reasons for absence in a school (one month)</b>" + tbl(["Reason", "Number of students"], [["Illness", "60"], ["Family functions", "25"], ["Travel", "10"], ["Other", "5"]]), "The table shows why 100 students were absent from school during a month. Illness is the main reason, with 60 students, which is 60 per cent of the absences. Family functions come next with 25 students, followed by travel with 10 and other causes with 5. The figures show that health is the biggest cause of lost school days. The school can therefore help by promoting hygiene, holding health check-ups and providing nutritious meals. Parents may be asked to plan family events during holidays. If the school and parents work together, attendance can improve and learning will not be interrupted." + FA),
      A(AP + "<br><b>Vehicles crossing a school gate between 8 and 9 a.m.</b>" + tbl(["Type", "Number"], [["Two-wheelers", "120"], ["Cars", "60"], ["Cycles", "20"], ["Buses", "10"]]), "The data record 210 vehicles crossing the school gate in one hour. Two-wheelers are the most common at 120, more than half the total. Cars come next with 60, while only 20 cycles and 10 buses were counted. The small number of cycles and buses suggests that students rely on private vehicles, which causes congestion and pollution at the gate. The school may encourage car-pooling and cycling, ask the transport office to add bus routes and mark a separate lane for pedestrians. Such steps will make the area safer and cleaner for students." + FA))
ANA[3] = (A(AP + "<br><b>Sources of electricity in a state (per cent)</b>" + tbl(["Source", "Share"], [["Coal", "60%"], ["Hydro", "15%"], ["Solar and wind", "20%"], ["Others", "5%"]]), "The table shows the sources of the state's electricity. Coal contributes the largest share, 60 per cent, which makes the state heavily dependent on a polluting fuel. Solar and wind together provide 20 per cent, while hydro-power accounts for 15 per cent and other sources for 5 per cent. Since coal is limited and harms the environment, the state should increase the share of renewable sources. Subsidies for rooftop solar panels, investment in wind farms and public awareness campaigns can help reduce the dependence on coal and ensure a cleaner future." + FA),
      A(AP + "<br><b>Marks of students in different types of study habits (average out of 100)</b>" + tbl(["Study habit", "Average marks"], [["Regular daily study", "78"], ["Study only before exams", "55"], ["Group study", "70"], ["No fixed routine", "48"]]), "The table compares average marks according to study habits. Students who study regularly every day score the highest, with an average of 78, while those with no fixed routine score the lowest at 48. Group study yields 70 marks, which is also high, and those who study only before the examination score 55. The figures prove that consistency matters more than last-minute effort. Students should make a timetable, revise daily and study with friends when they find a topic difficult. Teachers can support this by assigning regular homework and holding revision sessions." + FA))
ANA[4] = (A(AP + "<br><b>Literacy rate in a district (per cent)</b>" + tbl(["Year", "Male", "Female"], [["2001", "70", "45"], ["2011", "78", "58"], ["2021", "85", "72"]]), "The table shows the literacy rates of a district over twenty years. Male literacy rose from 70 per cent in 2001 to 85 per cent in 2021, a gain of 15 points. Female literacy grew faster, from 45 to 72 per cent, a rise of 27 points. Although the gap between the sexes has narrowed from 25 to 13 points, it has not yet closed. The trend shows that campaigns for girls' education have succeeded. Yet further efforts, such as free uniforms and safe transport for girls, are needed to reach full equality." + FA),
      A(AP + "<br><b>Time spent by Class 10 students in a day (hours)</b>" + tbl(["Activity", "Hours"], [["School", "6"], ["Study at home", "3"], ["Sleep", "7"], ["Screen entertainment", "3"], ["Play and others", "5"]]), "The table shows how a Class 10 student spends 24 hours. Sleep takes 7 hours and school 6 hours. Study at home takes 3 hours, equal to the time spent on screen entertainment, which suggests that a good deal of time is spent in leisure. Play and other activities take 5 hours. Considering the importance of the board examination, the time given to screens could be reduced by an hour and used for revision or outdoor play. A balanced schedule that includes adequate sleep, study and exercise will help students perform better." + FA))
ANA[5] = (A(AP + "<br><b>Daily newspaper readers in a town by age group (per cent)</b>" + tbl(["Age group", "Readers"], [["Below 18", "10%"], ["18–35", "35%"], ["36–60", "40%"], ["Above 60", "15%"]]), "The table shows the percentage of newspaper readers in a town by age. Those between 36 and 60 form the largest group at 40 per cent, followed by the 18–35 group at 35 per cent. The share of readers below 18 is only 10 per cent, which means that the young have little interest in newspapers. The 15 per cent of readers above 60 may be due to their leisure. To develop reading habits, schools can introduce newspaper reading in the morning assembly and encourage students to read editorials. Newspapers can also publish special pages for young readers." + FA),
      A(AP + "<br><b>Participation in school clubs (Class 10)</b>" + tbl(["Club", "Students"], [["Science", "40"], ["Sports", "55"], ["Literary", "25"], ["Art and music", "30"]]), "The table gives the membership of four clubs among 150 students. The Sports Club is the most popular, with 55 members, followed by the Science Club with 40. The Art and Music Club has 30 members, while the Literary Club has only 25. This indicates that students favour active and practical pursuits. The school should boost the Literary Club by organising debates and storytelling competitions. Clubs help students discover talents and build confidence, so every student should be encouraged to join at least one." + FA))
G_NEW = {
1: [g("Edit the sentence by correcting the error: She go to school by bus every day.", "She goes to school by bus every day."),
    g("Fill in the blank with the correct form of the verb: Neither the boys nor the teacher ______ (be) present.", "was (the verb agrees with the nearer subject 'teacher').")],
2: [g("Edit: He is the taller of the three boys.", "He is the tallest of the three boys."),
    g("Fill in the blank: Each of the students ______ (have) a library card.", "has.")],
3: [g("Edit: He did not came to school yesterday.", "He did not come to school yesterday."),
    g("Fill in the blank with a suitable modal: You ______ have told me earlier. (expressing regret)", "should (or ought to).")],
4: [g("Edit: There is many reasons for his failure.", "There are many reasons for his failure."),
    g("Fill in the blank with the correct tense: She ______ (watch) television when the lights went off.", "was watching.")],
5: [g("Edit: I have been knowing him since 2010.", "I have known him since 2010."),
    g("Fill in the blank with a suitable determiner: He gave me ______ advice. (not any)", "some (or little).")],
}

NEWB[2] = L("You are Kiran/Karan of 8, Subhash Marg, Kota. You ordered a school bag online from 'BagWorld' but received a different colour and a torn zip. Write a letter in 100–120 words to the Customer Care Manager complaining and requesting a replacement.", "8, Subhash Marg<br>Kota<br>5 November 2026<br>The Customer Care Manager<br>BagWorld<br>Jaipur<br>Subject: Complaint about wrong and damaged school bag (Order No. 7816)<br>Sir/Madam,<br>On 25 October 2026 I ordered a navy-blue school bag through your website. The parcel received on 3 November contains a red bag whose zip is torn. I have not used it. I request you to collect the bag and send the correct one within a week, or refund the amount of ₹899. I am attaching photographs and a copy of the invoice. I hope you will treat the matter as urgent.<br>Yours faithfully<br>Kiran/Karan" + FL)
NEWB[3] = L("You are Sonal/Sandeep, a student of Class 10. Write a letter in 100–120 words to the Principal of 'Excel Academy', Jaipur, enquiring about the facilities and fees of the career-guidance programme for Class 10 students.", "11, Civil Lines<br>Jaipur<br>8 November 2026<br>The Principal<br>Excel Academy<br>Jaipur<br>Subject: Enquiry about the career-guidance programme<br>Sir/Madam,<br>I have learnt from your brochure that you conduct a career-guidance programme for Class 10 students. I would be grateful if you could send me details regarding the dates, the number of sessions, the experts who conduct them and the fees. Kindly also let me know whether aptitude tests are included and whether students of other schools may enrol. I should like to join if the timings do not clash with my school hours.<br>Yours faithfully<br>Sonal/Sandeep" + FL)
NEWB[4] = L("You are Reena/Ravi of 15, Vidya Nagar, Bikaner. Write a letter in 100–120 words to the Editor of a local daily on the heavy traffic jams near schools during opening and closing hours and suggest measures.", "15, Vidya Nagar<br>Bikaner<br>10 November 2026<br>The Editor<br>The Desert Times<br>Bikaner<br>Subject: Traffic jams near schools<br>Sir/Madam,<br>Through your newspaper I wish to draw attention to the daily traffic jams near the schools of Vidya Nagar. Parents' cars and auto-rickshaws stop in the middle of the road, and children find it difficult to cross. I suggest that the traffic police be posted at peak hours, that no-parking zones be marked and that schools stagger their timings. Parents should use car-pools and drop children at a safe distance from the gate. I hope this will be given prompt attention.<br>Yours faithfully<br>Reena/Ravi" + FL)
NEWB[5] = L("You are Gaurav/Gauri, Head Boy/Head Girl of your school in Kota. Write a letter in 100–120 words to the Principal, requesting permission to organise a 'Clean Campus' drive on a Saturday.", "Mastermind Public School<br>Kota<br>12 November 2026<br>The Principal<br>Mastermind Public School<br>Kota<br>Subject: Permission for a Clean Campus drive<br>Respected Madam/Sir,<br>I request your permission to organise a Clean Campus drive on Saturday, 21 November 2026, from 8 to 11 a.m. About eighty volunteers from Classes 8 to 12 will clean the playground, the corridors and the garden under the guidance of the Eco Club teachers. Brooms, gloves and bags will be arranged by the club. We shall segregate the waste and give the dry waste for recycling. I assure you that the drive will be well organised and orderly. I shall be grateful for your consent.<br>Yours obediently<br>Gaurav/Gauri<br>Head Boy/Head Girl" + FL)
